尾入口和计数让常见查询更快，却增加维护责任。若只更新连接忘了计数，显示项数会错；若只清计数不清入口，遍历又可能读旧节点。关于const的阅读例进一步说明，保护一个头指针对象并不自动保护其后所有节点。

# 17.4 队列ADT

队列在序列基础上限制操作位置：从尾部加入，从头部取走，形成先进先出。它可以用链式节点或环形数组实现，接口不应把某一种存储方式误当成队列定义本身。

### 环形数组用首下标与计数区别空和满（完整C程序）

```c
#include <stdio.h>
#define CAPACITY 3
struct queue {
    int front;
    int count;
};
void initialize(struct queue *queue)
{
    queue->front = 0;
    queue->count = 0;
}
int enqueue(int value, int data[], struct queue *queue)
{
    if (queue->count == CAPACITY)
        return 0;
    int index = (queue->front + queue->count) % CAPACITY;
    data[index] = value;
    ++queue->count;
    return 1;
}
int dequeue(int *value, const int data[], struct queue *queue)
{
    if (queue->count == 0)
        return 0;
    *value = data[queue->front];
    queue->front = (queue->front + 1) % CAPACITY;
    --queue->count;
    return 1;
}
int main(void)
{
    int data[CAPACITY];
    struct queue queue;
    initialize(&queue);
    int value = 777;
    int obtained = dequeue(&value, data, &queue);
    printf("empty-pop=%d unchanged=%d\n", obtained, value);
    enqueue(10, data, &queue);
    enqueue(20, data, &queue);
    enqueue(30, data, &queue);
    int extra = enqueue(40, data, &queue);
    printf("extra=%d full-count=%d\n", extra, queue.count);
    if (dequeue(&value, data, &queue))
        printf("first=%d\n", value);
    enqueue(40, data, &queue);
    while (dequeue(&value, data, &queue))
        printf("next=%d\n", value);
    printf("empty=%d count=%d\n", queue.count == 0, queue.count);
    enqueue(50, data, &queue);
    if (dequeue(&value, data, &queue))
        printf("reused=%d\n", value);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
empty-pop=0 unchanged=777
extra=0 full-count=3
first=10
next=20
next=30
next=40
empty=1 count=0
reused=50
```

这里把固定数组和保存首下标、数量的状态分开传入，调用时须保证数组容量与队列约定一致。出队通过移动首下标完成，不需要每次搬移其他元素；取余让空出的数组位置可再次利用。

队列满和空分别由数量等于容量与0判断。失败出队保持输出对象不变，失败入队保持队列内容不变，后面完整链式接口采用相同的可观察约定。


队列的要点在操作顺序：尾部加入、头部取出，最早加入且未取走的项最先出来。环形数组和链式节点都能实现它，二者内部位置不同，不改变FIFO含义。

环形数组通过首下标与count计算可用位置，出队后不需要搬动其余元素。位置回绕只是重新利用空槽，不能让新项越过旧项。失败出队不改输出对象、失败入队不改现有序列，是使用者可以依赖的接口规则。

