**queue.c**

```c
#include <stdlib.h>
#include "queue.h"
struct queue_node {
    Item item;
    QueueNode *next;
};
void QueueInit(Queue *queue)
{
    queue->front = NULL;
    queue->rear = NULL;
    queue->count = 0;
}
bool QueueIsEmpty(const Queue *queue)
{
    return queue->count == 0;
}
bool QueueIsFull(const Queue *queue)
{
    return queue->count == QUEUE_CAPACITY;
}
int QueueCount(const Queue *queue)
{
    return queue->count;
}
bool QueuePush(Item item, Queue *queue)
{
    if (QueueIsFull(queue))
        return false;
    QueueNode *node = malloc(sizeof *node);
    if (node == NULL)
        return false;
    node->item = item;
    node->next = NULL;
    if (queue->rear == NULL)
        queue->front = node;
    else
        queue->rear->next = node;
    queue->rear = node;
    ++queue->count;
    return true;
}
bool QueuePop(Item *item, Queue *queue)
{
    if (QueueIsEmpty(queue))
        return false;
    QueueNode *old = queue->front;
    *item = old->item;
    queue->front = old->next;
    --queue->count;
    /* 删除最后一项后，rear也必须回到空状态。 */
    if (queue->count == 0)
        queue->rear = NULL;
    free(old);
    return true;
}
void QueueClear(Queue *queue)
{
    Item unused;
    while (QueuePop(&unused, queue)) {
    }
}
```

**教学预期（非本平台实测）**：固定种子只使同一实现的同次随机序列可复现，不给跨实现固定统计数。成功运行时accepted=started+waiting，started=completed+busy；平均等待分母是已开始服务人数。到达模型每分钟至多一人，结束时不自动继续服务剩余顾客。

随机版复用相同队列实现，只换顾客项类型，最多每分钟到一人，属于离散的简化模型，不能照搬成任意到达率的连续时间现实过程。固定种子不保证跨实现相同统计；`rand()%3`也不是严格无偏随机生成方法。更长样本能减少部分随机波动，但不会自动修复模型假设。


把固定例子的六轮摊开，可以看清“已开始”和“已完成”为何不同。下面分钟编号与程序一致，从0开始；顾客也按数组索引0至3称呼。每轮先到达，再启动服务、消耗一分钟，最后统计等待人数。

| 分钟 | 本轮到达 | 本轮开始服务 | 轮末等待数 | 累计完成数 |
| --- | --- | --- | --- | --- |
| 0 | 顾客0接纳 | 顾客0 | 0 | 0 |
| 1 | 顾客1接纳 | 无 | 1 | 0 |
| 2 | 顾客2接纳 | 无 | 2 | 1 |
| 3 | 顾客3因满被拒绝 | 顾客1 | 1 | 1 |
| 4 | 无 | 无 | 1 | 2 |
| 5 | 无 | 顾客2 | 0 | 3 |

轮末等待数合计5，除六轮得到约0.83；三位已开始者分别等待0、2、3分钟，合计5，除3得到约1.67。若只运行四轮，就不能把未开始者也算进开始等待平均的分母。统计口径和事件先后共同决定结果，不只是队列是否实现正确。

# 17.6 链表和数组

数组提供常数时间的下标定位；普通单向链表需要沿连接走到目标位置。数组在中间插删通常要移动后续元素，链表在已知前驱的位置附近只需改少量连接，但寻找该位置和申请节点的成本不能省略。

### 数组移动元素，链表修改已有位置附近的连接（完整C程序）

```c
#include <stdio.h>
#include <stddef.h>
struct node {
    int value;
    struct node *next;
};
struct node last = {5, NULL};
struct node middle = {3, &last};
struct node first = {1, &middle};
struct node added = {2, NULL};
void show(const struct node *node)
{
    while (node != NULL) {
        printf(" %d", node->value);
        node = node->next;
    }
    putchar('\n');
}
int main(void)
{
    int values[6] = {1, 3, 5};
    int count = 3;
    int position = 1;
    for (int i = count; i > position; --i)
        values[i] = values[i - 1];
    values[position] = 2;
    ++count;
    printf("array-insert:");
    for (int i = 0; i < count; ++i)
        printf(" %d", values[i]);
    putchar('\n');
    position = 2;
    for (int i = position; i + 1 < count; ++i)
        values[i] = values[i + 1];
    --count;
    printf("array-delete:");
    for (int i = 0; i < count; ++i)
        printf(" %d", values[i]);
    putchar('\n');
    added.next = first.next;
    first.next = &added;
    printf("list-insert:");
    show(&first);
    added.next = middle.next;
    printf("list-delete:");
    show(&first);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
array-insert: 1 2 3 5
array-delete: 1 2 5
list-insert: 1 2 3 5
list-delete: 1 2 5
```

数组插入从后向前移动，避免覆盖尚未搬走的值；链表先保存旧后继到新节点，再接入前驱。这里的节点是静态对象，删除只把它从链上摘下，没有释放它，也不能对它调用`free`。

### 有序数组二分查找维护剩余闭区间（完整C程序）

```c
#include <stdio.h>
int find(const int values[], int count, int target)
{
    int low = 0;
    int high = count - 1;
    while (low <= high) {
        int middle = low + (high - low) / 2;
        if (values[middle] == target)
            return middle;
        if (values[middle] < target)
            low = middle + 1;
        else
            high = middle - 1;
    }
    return -1;
}
int main(void)
{
    int values[5] = {1, 3, 5, 7, 9};
    printf("five=%d eight=%d first=%d last=%d empty=%d\n",
           find(values, 5, 5), find(values, 5, 8), find(values, 5, 1),
           find(values, 5, 9), find(values, 0, 1));
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
five=2 eight=-1 first=0 last=4 empty=-1
```

二分查找依赖有序和快速取中间项。普通单链表也能按中点思路分区，但寻找中点仍要走连接，得不到数组那样的整体对数访问效率，不能简单说在链表上“绝对不能”二分。数组也能运行时分配，不是所有数组容量都必须在编译时决定；树同样不是对所有操作都必胜的替代品。


比较插入成本时，要同时注明已知条件。已知链表前驱后，接入只改少量连接；若先要找第几项，还需沿链行走。数组中间插入通常移动后续项，但它能直接取中间下标，适合有序二分。

数组移动应从后向前给新项腾位置，避免覆盖尚未搬走的值；链式插入则先让新节点保存旧后继，再更新前驱，避免丢链。不能从“只改两个指针”推出整个查找与插入任务永远常数时间，定位和分配也属于真实成本。

# 17.7 二叉查找树

二叉查找树的每个节点有至多两个子节点。不变量约束整棵子树：左侧所有键都在当前键之前，右侧所有键都在之后，不能只比较两个直接子节点就认为整棵树有效。

### 按整棵子树的次序约定查找与中序遍历（完整C程序）

```c
#include <stdio.h>
#include <stddef.h>
struct node {
    int key;
    struct node *left;
    struct node *right;
};
struct node one = {1, NULL, NULL};
struct node three = {3, NULL, NULL};
struct node five = {5, NULL, NULL};
struct node seven = {7, NULL, NULL};
struct node two = {2, &one, &three};
struct node six = {6, &five, &seven};
struct node four = {4, &two, &six};
int contains(const struct node *root, int key)
{
    const struct node *current = root;
    while (current != NULL) {
        if (key == current->key)
            return 1;
        current = key < current->key ? current->left : current->right;
    }
    return 0;
}
void inorder(const struct node *root)
{
    if (root == NULL)
        return;
    inorder(root->left);
    printf(" %d", root->key);
    inorder(root->right);
}
int height(const struct node *root)
{
    if (root == NULL)
        return 0;
    int left = height(root->left);
    int right = height(root->right);
    return 1 + (left > right ? left : right);
}
int main(void)
{
    int key;
    if (scanf("%d", &key) != 1) {
        puts("no key");
        return 0;
    }
    printf("ordered:");
    inorder(&four);
    putchar('\n');
    printf("key=%d found=%d empty=%d height=%d\n", key,
           contains(&four, key), contains(NULL, key), height(&four));
    return 0;
}
```

**输入**：

```text
3
```

**真实C6运行结果**：

```text
ordered: 1 2 3 4 5 6 7
key=3 found=1 empty=0 height=3
```

查找每次依据次序进入一个子树，遇空入口则表示不存在。中序遍历先左、再当前、再右，在不变量成立时得到升序。这个完整小树用现成节点真实观察查找、遍历和高度，动态增加和删除另有完整阅读实现。

一次比较可以排除另一个子树，却不保证恰好排除一半节点。成本由树高控制，平衡时可为对数级，极端偏斜时会退化为线性。


查找目标时，只进入比较结果指向的一棵子树，因为另一侧所有键都已按不变量排除。这个保证覆盖整棵子树，不是只要求父子之间大小正确；深处某个键越界也会破坏查找。

每次排除一侧不等于恰好排除一半节点，树高才控制路径长度。中序遍历在不变量成立时给出排序结果，可以用来检查更新后关系，但还要另外核对计数、重复政策与资源状态，不能只凭一串有序输出证明全部实现正确。

# 17.7.1 二叉树ADT

建立树ADT时，要先决定键、重复规则、容量和操作合同。这里按“名字，再按种类”比较宠物，两个字段都相同才是重复；同名猫和同名狗可以各占一项。

### 完整树接口覆盖重复、满容量和三种删除（完整标准C阅读程序）

动态分配、用户头、结构复制、回调及指向指针的接口超出C6范围。三个文件保留完整实现，不以静态节点代替动态删除运行。

**main.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include "tree.h"
void print_item(const Item *item)
{
    printf("%s %s\n", item->name, item->kind);
}
int main(void)
{
    Tree pets;
    TreeInit(&pets);
    Item input[7] = {{"MILO", "CAT"}, {"ARI", "DOG"}, {"ZOE", "CAT"},
                     {"ABE", "BIRD"}, {"BO", "CAT"}, {"TESS", "DOG"},
                     {"UMA", "CAT"}};
    for (size_t i = 0; i < 7; ++i) {
        if (TreeAdd(&input[i], &pets) != TREE_ADDED) {
            TreeClear(&pets);
            return EXIT_FAILURE;
        }
    }
    Item extra = {"SAM", "DOG"};
    int duplicate = TreeAdd(&input[0], &pets);
    int full = TreeAdd(&extra, &pets);
    printf("count=%zu duplicate=%d full=%d absent=%d\n",
           TreeCount(&pets), duplicate, full, TreeContains(&extra, &pets));
    int removed = TreeRemove(&input[3], &pets);
    printf("leaf=%d count=%zu\n", removed, TreeCount(&pets));
    removed = TreeRemove(&input[5], &pets);
    printf("single=%d count=%zu\n", removed, TreeCount(&pets));
    removed = TreeRemove(&input[0], &pets);
    printf("double=%d count=%zu\n", removed, TreeCount(&pets));
    TreeVisit(&pets, print_item);
    removed = TreeRemove(&extra, &pets);
    printf("missing=%d count=%zu\n", removed, TreeCount(&pets));
    TreeClear(&pets);
    TreeClear(&pets);
    printf("count=%zu\n", TreeCount(&pets));
    return 0;
}
```

