两子树删除采用本节明确政策：找到左子树最右端，把旧右子树接到它的右侧，再让左子树接替旧入口。因为左侧所有键都小于被删键，而右侧所有键都大于被删键，把右子树接到左侧最大键之后仍保持整体次序。

link指向需要改写的入口，所以同一套逻辑既可改根，也可改父节点的某个子入口。删除完成还要释放旧节点并更新数量；只看到数量从7减少，不足以证明剩余四键中序正确。清空则先处理子树，再释放当前节点，避免之后读取已失效成员。

# 17.7.4 使用二叉树

使用树的业务程序负责取得完整记录、统一规范键和处理接口返回；它不应直接更改节点排序字段。菜单中的查找、添加和删除必须采用同一份键规范，否则加入小写名后可能用另一种规则查不到。

### 菜单只调用树接口，键规范化保持一致（完整标准C阅读程序）

此完整标准C菜单与tree.h、tree.c共同构成程序；动态树、用户头和多文件链接超出C6范围。输入约定为无内嵌NUL的文本行。

**main.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "tree.h"
int read_line(char text[], int capacity)
{
    if (fgets(text, capacity, stdin) == NULL)
        return 0;
    char *newline = strchr(text, '\n');
    if (newline != NULL) {
        *newline = '\0';
        return 1;
    }
    int ch = getchar();
    if (ch == '\n' || ch == EOF)
        return 1;
    while (ch != '\n' && ch != EOF)
        ch = getchar();
    return -1;
}
int read_item(Item *item)
{
    puts("name:");
    int status = read_line(item->name, 20);
    if (status <= 0)
        return status;
    puts("kind:");
    status = read_line(item->kind, 20);
    if (status <= 0)
        return status;
    if (item->name[0] == '\0' || item->kind[0] == '\0')
        return -1;
    for (size_t i = 0; item->name[i] != '\0'; ++i)
        item->name[i] = (char)toupper((unsigned char)item->name[i]);
    for (size_t i = 0; item->kind[i] != '\0'; ++i)
        item->kind[i] = (char)toupper((unsigned char)item->kind[i]);
    return 1;
}
void print_item(const Item *item)
{
    printf("%s %s\n", item->name, item->kind);
}
int main(void)
{
    Tree pets;
    TreeInit(&pets);
    char command[8];
    for (;;) {
        puts("a:add f:find d:delete l:list n:count q:quit");
        int status = read_line(command, 8);
        if (status == 0)
            break;
        if (status < 0 || command[0] == '\0' || command[1] != '\0') {
            puts("invalid command");
            continue;
        }
        int choice = tolower((unsigned char)command[0]);
        if (choice == 'q')
            break;
        if (choice == 'l') {
            TreeVisit(&pets, print_item);
            continue;
        }
        if (choice == 'n') {
            printf("count=%zu\n", TreeCount(&pets));
            continue;
        }
        if (choice != 'a' && choice != 'f' && choice != 'd') {
            puts("invalid command");
            continue;
        }
        Item item;
        status = read_item(&item);
        if (status == 0)
            break;
        if (status < 0) {
            puts("invalid item");
            continue;
        }
        if (choice == 'f')
            printf("found=%d\n", TreeContains(&item, &pets));
        else if (choice == 'd')
            printf("removed=%d\n", TreeRemove(&item, &pets));
        else {
            enum AddResult result = TreeAdd(&item, &pets);
            if (result == TREE_ADDED)
                puts("added");
            else if (result == TREE_DUPLICATE)
                puts("duplicate");
            else if (result == TREE_FULL)
                puts("full");
            else
                puts("no memory");
        }
    }
